    p = os.path.join(V2R, "prompts", f"boar_{a}.txt"); open(p, "w", encoding="utf-8").write(HEAD + ACT[a] + TAIL + "\n"); print("写好了", p, len(HEAD + ACT[a] + TAIL), "字")
